<?php
require 'db.php'; require_admin();
$message='';
$editRow=null; if(isset($_GET['edit'])) { $eq=$pdo->prepare('SELECT * FROM students WHERE id=?'); $eq->execute([(int)$_GET['edit']]); $editRow=$eq->fetch(); }
if ($_SERVER['REQUEST_METHOD']==='POST') {
 $action=$_POST['action']??''; $id=(int)($_POST['id']??0);
 if ($action==='delete' && $id) { $pdo->prepare('DELETE FROM students WHERE id=?')->execute([$id]); $message='Student record deleted.'; }
 if ($action==='save') {
  $name=trim($_POST['full_name']??''); $email=strtolower(trim($_POST['email']??'')); $course=trim($_POST['course']??''); $year=(int)($_POST['year_level']??1);
  if (mb_strlen($name)<2 || !filter_var($email,FILTER_VALIDATE_EMAIL) || $course==='' || $year<1 || $year>6) $message='Please enter valid student details.';
  else { try { if($id) { $q=$pdo->prepare('UPDATE students SET full_name=?,email=?,course=?,year_level=? WHERE id=?'); $q->execute([$name,$email,$course,$year,$id]); } else { $q=$pdo->prepare('INSERT INTO students(full_name,email,course,year_level) VALUES(?,?,?,?)'); $q->execute([$name,$email,$course,$year]); } $message='Student record saved.'; } catch(PDOException $e) { $message='Could not save. Check that the email is unique.'; } }
 }
}
$search=trim($_GET['q']??''); $sql='SELECT * FROM students'; $params=[]; if($search!==''){ $sql.=' WHERE full_name LIKE ? OR email LIKE ? OR course LIKE ?'; $like="%$search%"; $params=[$like,$like,$like]; } $sql.=' ORDER BY id DESC'; $q=$pdo->prepare($sql); $q->execute($params); $rows=$q->fetchAll();
?>
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Management</title><style>body{font:15px system-ui;background:#f4f7fb;color:#172033;margin:0;padding:25px}.wrap{max-width:1100px;margin:auto}.panel{background:white;padding:20px;border-radius:14px;margin:16px 0;overflow:auto}input,select{padding:9px;border:1px solid #ccd3df;border-radius:7px;margin:4px}button{padding:9px 13px;background:#3157d5;color:white;border:0;border-radius:7px;cursor:pointer}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #e4e9f1}a{color:#3157d5}.msg{padding:12px;background:#e8f8ee;border-radius:8px}</style><main class="wrap"><p><a href="dashboard.php">← Dashboard</a></p><h1>Student records</h1><?php if($message):?><p class="msg"><?=h($message)?></p><?php endif;?><section class="panel"><h2><?= $editRow ? 'Edit student' : 'Add a student' ?></h2><form method="post"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=h($editRow['id']??'')?>"><input name="full_name" placeholder="Full name" value="<?=h($editRow['full_name']??'')?>" required><input type="email" name="email" placeholder="Email" value="<?=h($editRow['email']??'')?>" required><input name="course" placeholder="Course" value="<?=h($editRow['course']??'')?>" required><select name="year_level"><option value="1" <?=($editRow['year_level']??1)==1?'selected':''?>>Year 1</option><option value="2" <?=($editRow['year_level']??0)==2?'selected':''?>>Year 2</option><option value="3" <?=($editRow['year_level']??0)==3?'selected':''?>>Year 3</option><option value="4" <?=($editRow['year_level']??0)==4?'selected':''?>>Year 4</option></select><button>Save student</button> <?php if($editRow):?><a href="students.php">Cancel edit</a><?php endif;?></form></section><section class="panel"><form method="get"><input name="q" value="<?=h($search)?>" placeholder="Search name, email or course"><button>Search</button> <a href="students.php">Clear</a></form><p><?=count($rows)?> record(s)</p><table><thead><tr><th>ID</th><th>Name</th><th>Email</th><th>Course</th><th>Year</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=h($r['full_name'])?></td><td><?=h($r['email'])?></td><td><?=h($r['course'])?></td><td><?=$r['year_level']?></td><td><a href="?edit=<?=$r['id']?>">Edit</a> <form style="display:inline" method="post" onsubmit="return confirm('Delete this student?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button>Delete</button></form></td></tr><?php endforeach;?></tbody></table></section></main></html>
